import { easeCubicInOut } from 'd3-ease';
import { interpolateNumber as interpolate } from 'd3-interpolate';

import {
  FnCanvasAccessor,
  AreaCanvasInstance,
} from '../../types/canvas-shape.js';
import { areDatumsEqualBy } from '../datums.js';

/**
 * Check if current and prev area canvas are equal.
 * By comparing all incoming data and x/y accessors value.
 *
 * @param current - current bar canvas
 * @param prev - prev bar canvas
 * @returns boolean
 */
export function isAreaCanvasEqual<Datum>(
  current: AreaCanvasInstance<Datum>,
  prev: AreaCanvasInstance<Datum>,
): boolean {
  if (!areDatumsEqualBy(current.data, prev.data, 'value')) {
    return false;
  }

  const isNotResizing =
    current.canvasWidth === prev.canvasWidth &&
    current.canvasHeight === prev.canvasHeight;

  if (isNotResizing) {
    return (
      prev.y0(prev.data[0]) === current.y0(current.data[0]) &&
      prev.y1(prev.data[0]) === current.y1(current.data[0]) &&
      current.x(current.data[0]) === prev.x(prev.data[0])
    );
  }

  return true;
}

interface AnimationPoints<Datum> {
  start?: Datum;
  end: Datum;
}

/**
 * Get start and end points to be animated.
 *
 * @param canvas - current canvas, end
 * @param prevCanvas - previous canvas, start
 * @returns - array of start and end points store by current canvas (End) position
 */
function getAnimationPoints<Datum>(
  canvas: AreaCanvasInstance<Datum>,
  prevCanvas?: AreaCanvasInstance<Datum>,
) {
  const startEndPoints: AnimationPoints<Datum>[] = [];
  const dataLength = canvas.data.length;

  for (let i = 0; i < dataLength; i++) {
    const end = canvas.data[i];

    if (!prevCanvas) {
      startEndPoints.push({ start: undefined, end });

      continue;
    }

    const prevPoint = prevCanvas.data[i];

    startEndPoints.push({ start: prevPoint, end });
  }

  return startEndPoints;
}

/**
 * AreaCanvas animation.
 * Area animation logic based on elapsed, considering origin (prevCanvas) and end (canvas) points.
 * After all calculations, it will execute printArea callback
 * @param canvas - current canvas, where the animation ends
 * @param prevCanvas - previous canvas, where the animation starts
 * @param currentGroupedData - grouped of datums by id
 * @param prevGroupedData - previous grouped of datums by id
 * @param elapsed - variable value, depends on animation laps
 * @param duration - animation duration(s) EG: 400 === 4ms
 * @param printArea - print area call back
 */
export function areaAnimation<Datum>(
  canvas: AreaCanvasInstance<Datum>,
  progress: number,
  printArea: (
    x: FnCanvasAccessor<Datum>,
    y0: FnCanvasAccessor<Datum>,
    y1: FnCanvasAccessor<Datum>,
  ) => void,
  prevCanvas?: AreaCanvasInstance<Datum>,
) {
  const animationPoints = getAnimationPoints<Datum>(canvas, prevCanvas);

  const interpolation = (start: number, end: number) =>
    interpolate(start, end)(easeCubicInOut(progress));

  const x = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (start && prevCanvas) {
      return interpolation(prevCanvas.x(start), canvas.x(end));
    }

    return canvas.x(end);
  };

  const y0 = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (start && prevCanvas) {
      return interpolation(prevCanvas.y0(start), canvas.y0(end));
    }

    return interpolation(canvas.zeroAxis(point), canvas.y0(end));
  };

  const y1 = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (start && prevCanvas) {
      return interpolation(prevCanvas.y1(start), canvas.y1(end));
    }

    return interpolation(canvas.zeroAxis(point), canvas.y1(end));
  };

  return printArea(x, y0, y1);
}
